  constructor(speed) {
    this.r = Math.random() * 15 + 10;
    this.x = w + this.r;
    this.y = Math.random() * (h - this.r * 2) + this.r;
    this.vx = -speed * (0.5 + Math.random() * 0.5);
    this.angle = Math.random() * Math.PI * 2;
    this.rotateSpeed = (Math.random() - 0.5) * 0.02;
  }
  update() {
    this.x += this.vx;
    this.angle += this.rotateSpeed;
